import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"叙事与伏笔","description":"","frontmatter":{},"headers":[],"relativePath":"叙事与伏笔/index.md","filePath":"叙事与伏笔/index.md","lastUpdated":1786679977000}'),o={name:"叙事与伏笔/index.md"};function i(n,a,s,d,h,c){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="叙事与伏笔" tabindex="-1">叙事与伏笔 <a class="header-anchor" href="#叙事与伏笔" aria-label="Permalink to &quot;叙事与伏笔&quot;">​</a></h1><p>本目录管理神造物世界观中的<strong>伏笔系统</strong>：将设定中的未解之谜统一编号（F-xx），按&quot;洋葱层&quot;分类维护。它同时是<strong>跨层导航中枢</strong>——无论你在表层、中层还是底层读到哪个谜团，都可以回到这里，跟随层级徽标前往真相所在。</p><h2 id="洋葱层结构" tabindex="-1">洋葱层结构 <a class="header-anchor" href="#洋葱层结构" aria-label="Permalink to &quot;洋葱层结构&quot;">​</a></h2><p>伏笔按可见程度分为三层：</p><ul><li><strong>表层伏笔</strong>：福瑞生灵能够察觉到的异常现象（如地脉的光芒、甲族灭绝的空白记录）。</li><li><strong>中层伏笔</strong>：涉及隐藏真相的谜团（如克隆仓库、上位毁灭神的本源）。</li><li><strong>底层伏笔</strong>：元规则层面的未解之谜（如玩家能力的本质、叙事逻辑的存在）。</li></ul><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><ul><li>伏笔在文中以 <code>[伏笔:F-xx]</code> 标记，指向下方清单。</li><li>伏笔清单仅记录&quot;谜面&quot;与状态，不记录揭晓方案。</li><li>状态分为：<strong>未揭晓</strong>（尚无人知晓答案）、<strong>部分揭晓</strong>（真相存在但未完全公开）、<strong>已揭晓</strong>（真相已写入设定文档）。</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./伏笔洋葱层分类">伏笔洋葱层分类</a></p></blockquote><h2 id="支线节点" tabindex="-1">支线节点 <a class="header-anchor" href="#支线节点" aria-label="Permalink to &quot;支线节点&quot;">​</a></h2><p>支线节点部分记录神造物世界观中某些特定历史分支与平行世界线中的重要事件节点。</p><h3 id="维斯塔黑化" tabindex="-1">维斯塔黑化 <a class="header-anchor" href="#维斯塔黑化" aria-label="Permalink to &quot;维斯塔黑化&quot;">​</a></h3><p>在玩家操作时间线的平行世界中，存在着维斯塔黑化的可能性。该支线描述了&quot;赤色暴君&quot;的世界线走向。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./维斯塔黑化" class="layer-link" data-layer="底层">维斯塔黑化</a></p></blockquote><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./伏笔洋葱层分类">伏笔洋葱层分类</a></li><li><a href="./维斯塔黑化" class="layer-link" data-layer="底层">维斯塔黑化</a></li><li><a href="./../表层/" class="layer-link" data-layer="表层">表层设定</a></li><li><a href="./../中层/" class="layer-link" data-layer="中层">中层设定</a></li><li><a href="./../底层/" class="layer-link" data-layer="底层">底层设定</a></li></ul><hr>',17)])])}const q=e(o,[["render",i]]);export{p as __pageData,q as default};
